mapper.select:
select ov.*,t.tearoom_name as tearoomName,g.goods_name as goodsName,u.user_name as userName,
       u.phone,o.orders_no as ordersNo,o.user_id as userId
from orders_video ov
left join orders o on o.orders_id=ov.orders_id
left join tearoom t on t.tearoom_id=ov.tearoom_id
left join goods g on g.goods_id=ov.goods_id
left join tb_user u on u.user_id=o.user_id
where 1=1

    and o.orders_id=#{ordersId}


    and o.tearoom_id=#{tearoomId}


    and o.goods_id=#{goodsId}


    and o.user_id=#{userId}


    and g.goods_name like concat('%',#{goodsName},'%')


    and u.user_name like concat('%',#{userName},'%')


    and u.phone like concat('%',#{phone},'%')


    and o.orders_no like concat('%',#{ordersNo},'%')


    and t.tearoom_name like concat('%',#{tearoomName},'%')


    and ov.classify=#{classify}


    and t.shopId=#{shopId}

order by ov.create_time desc
